function showNodeSkill(){const n=testingCapabilities?.nodes?.['testing:'+selectedStage]||{};if(!n.skill_view){notice('无 Skill 查看权限');return}if(!n.skill_import){notice('无 Skill 导入权限');return}skillContext={project:project.id,task:task.id,stage:selectedStage,revision:task.revision};const automated=[0,1,2,5].includes(selectedStage);modal(names[selectedStage]+' · Skill','<p>'+ (automated?'后续模型操作会加载本节点规则。':'此节点当前使用固定证据门禁和人工决策；Skill作为评审规范保存展示，不自动执行任意指令。')+' 修改规则不会自动重生成旧结果。仅导入单个 Markdown，外部引用文件不会自动导入。</p><input type="file" accept=".md" onchange="readNodeSkill(this)"><textarea id="node-skill-content" style="min-height:350px">'+escapeHtml(task.node_skills[String(selectedStage)].content)+'</textarea><button class="primary" onclick="saveNodeSkill()">保存节点 Skill</button>')}
async function readNodeSkill(input){const file=input.files[0];if(!file)return;if(!file.name.toLowerCase().endsWith('.md')||file.size>100000){notice('请选择100KB以内的Markdown Skill');return}$('node-skill-content').value=await file.text()}
async function saveNodeSkill(){const c=skillContext;if(!c||c.project!==project.id||c.task!==task.id||c.revision!==task.revision){notice('任务已变化，请重新打开');return}try{task=await api('/api/projects/'+c.project+'/tasks/'+c.task+'/node-skill?stage='+c.stage,{content:$('node-skill-content').value,revision:c.revision});closeModal();render();notice('Skill已保存，仅后续操作使用')}catch(e){notice(e.message)}}
async function exportNodeSkill(){const n=testingCapabilities?.nodes?.['testing:'+selectedStage]||{};if(!n.skill_view||!n.skill_export){notice('无 Skill 导出权限');return}try{const skill=await api('/api/projects/'+project.id+'/tasks/'+task.id+'/node-skill?stage='+selectedStage),url=URL.createObjectURL(new Blob([skill.content],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='TestFlow-'+names[selectedStage]+'-SKILL.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){notice(e.message)}}
async function handoffNodeSkill(){const stage=selectedStage,p=project?.id,t=task?.id,n=testingCapabilities?.nodes?.['testing:'+stage]||{};if(!n.skill_view||!n.skill_export){notice('无 Skill 导出权限');return}try{const result=await api('/api/projects/'+p+'/tasks/'+t+'/codex-handoff?stage='+stage,{origin:location.origin});StudioFlowCodexHandoff.beginCodexHandoff({uri:result.uri,openUri:StudioFlowCodexHandoff.openProtocolUri,onWaiting:()=>notice('正在请求本机 Codex 桥接工具…此时尚未确认接收'),onUnconfirmed:()=>recoverNodeSkillHandoff({project:p,task:t,stage})})}catch(e){notice(e.message)}}
async function recoverNodeSkillHandoff(context){if(project?.id!==context.project||task?.id!==context.task||selectedStage!==context.stage)return;try{const result=await api('/api/projects/'+context.project+'/tasks/'+context.task+'/codex-handoff?stage='+context.stage,{origin:location.origin,preview:true});if(project?.id!==context.project||task?.id!==context.task||selectedStage!==context.stage)return;const prompt=result.prompt;modal('尚未确认 Codex 接收','<p>浏览器无法确认本机桥接是否已安装，也无法确认 Codex 是否已粘贴。若 Codex 已出现，请在 Codex 检查内容；否则可复制下面的交接文本，手动粘贴到 Codex。</p><textarea id="codex-handoff-recovery" style="min-height:260px">'+escapeHtml(prompt)+'</textarea><button class="primary" onclick="copyNodeSkillHandoff()">复制交接文本</button><p class="small muted">未安装桥接工具：仓库内安装说明为 deploy/mac/codex-bridge/README.md。请安装维护者提供的桥接应用包；使用成品仅需 macOS 13+ 和 Codex 桌面 App。</p>')}catch(e){modal('无法准备手动交接','<p>桥接未确认，且读取当前节点 Skill 失败：'+escapeHtml(e.message)+'</p><p>请检查网络与节点权限后重试。</p>')}}
async function copyNodeSkillHandoff(){try{await navigator.clipboard.writeText($('codex-handoff-recovery').value);notice('交接文本已复制，请手动粘贴到 Codex')}catch(e){$('codex-handoff-recovery').select();notice('自动复制失败，请按 ⌘C 复制选中文本')}}

