function openNodeReset(){if(!task||selectedStage>task.stage||activeJob())return;resetContext={project:project.id,task:task.id,stage:selectedStage,revision:task.revision};const affected=Object.keys(task.artifacts).filter(key=>Number(key)>=selectedStage).map(key=>names[Number(key)]);modal('重置'+names[selectedStage]+'节点','<p>重置后从“'+names[selectedStage]+'”重新开始。'+(affected.length?'本节点及后续产物将归档并失效：'+affected.join('、')+'。':'当前没有需归档的节点产物。')+'</p><p>保留已导入需求、代码绑定、Skill和操作日志。已发布飞书Bug及状态台账保留，远端记录不会被修改；重新提单时需核对历史单据。</p><div class="field"><label>重置理由</label><input id="reset-reason" maxlength="1000" value="重新执行'+names[selectedStage]+'节点"></div><button class="primary" id="reset-confirm" onclick="confirmNodeReset()">确认重置此节点及后续结果</button>')}
async function confirmNodeReset(){const c=resetContext;if(!c||resetSending)return;if(project?.id!==c.project||task?.id!==c.task||task.revision!==c.revision){notice('任务已变化，请重新打开重置');return}resetSending=true;$('reset-confirm').disabled=true;try{const updated=await api('/api/projects/'+c.project+'/tasks/'+c.task+'/reset-node',{stage:c.stage,revision:c.revision,reason:$('reset-reason').value.trim(),confirmed:true});closeModal();if(project?.id===c.project&&task?.id===c.task){task=updated;selectedStage=c.stage;casePage=1;coveragePage=1;caseListExpanded=false;coverageExpanded=false;reviewExpanded=false;delete importFailures[c.task];sessionStorage.setItem('testflow-import-failures',JSON.stringify(importFailures));render()}resetContext=null;notice('节点已重置，旧结果已归档，等待重新操作')}catch(e){notice(e.message);if($('reset-confirm'))$('reset-confirm').disabled=false}finally{resetSending=false}}
function resetHistoryView(){const history=(task.reset_history||[]).map((r,i)=>({r,i})).filter(x=>x.r.stage===selectedStage);return history.length?'<details data-log-section="reset-history"><summary>重置记录 · '+history.length+' 次</summary>'+history.map(({r,i})=>'<div class="log"><time>'+escapeHtml(beijingTime(r.created_at))+'</time><br>'+escapeHtml(r.reason)+' <button onclick="showResetArchive('+i+')">查看归档单据</button></div>').join('')+'</details>':''}
function showResetArchive(index){const r=task.reset_history[index],known=[...r.remote_records,...r.publication_records];modal('重置前的单据记录','<p>'+escapeHtml(beijingTime(r.created_at))+' · '+escapeHtml(r.reason)+'</p>'+(known.length?known.map(x=>'<div class="evidence">记录：'+escapeHtml(x.record_id||'未知；结果不确定时需只读核对，禁止重发')+'<br>根因 / 发布标识：'+escapeHtml(x.root_cause_id||x.identity)+'<br>归档状态：'+escapeHtml(x.status||'已关联')+'</div>').join(''):'<p>此归档没有已知的飞书单据记录。</p>')+'<p>这是重置前的本地记录；当前飞书状态须重新读取核对。</p>')}

let aiCatalog=null,aiModelTab='relay';
